local zombie={}local _player=nil local _zombies=nil local _roundState=nil local _world=nil local _nav=nil local _settings=nil local _getTime=nil local _ccz=nil local _frame=nil function zombie.init(deps)_player=deps.player _zombies=deps.zombies _roundState=deps.roundState _world=deps.world _nav=deps.nav _settings=deps.settings _getTime=deps.getCurrentTime _ccz=deps.ccz _frame=deps.frame _onKill=deps.onKill end local ROUND={BASE_HP=150,HP_MULT_PER_ROUND=1.1,BASE_SPEED=2.8,SPEED_INC=0.15,MAX_SPEED=4.0,SPAWN_DELAY=2.0,MIN_SPAWN_DELAY=0.5,}function zombie.getZombieHealth(round)if round<=1 then return ROUND.BASE_HP elseif round<=9 then return math.floor(ROUND.BASE_HP*(ROUND.HP_MULT_PER_ROUND^(round-1)))else local r10hp=math.floor(ROUND.BASE_HP*(ROUND.HP_MULT_PER_ROUND^9))return r10hp+(round-10)*100 end end function zombie.getZombieSpeed(round)return math.min(ROUND.BASE_SPEED+(round-1)*ROUND.SPEED_INC,ROUND.MAX_SPEED)end function zombie.getZombiesPerRound(round)if round<=1 then return 6 end if round<=5 then return round*6 end return 24+(round-5)*6 end function zombie.getSpawnDelay(round)return math.max(ROUND.SPAWN_DELAY-round*0.08,ROUND.MIN_SPAWN_DELAY)end function zombie.startNewRound()_roundState.currentRound=_roundState.currentRound+1 _roundState.zombiesTotal=zombie.getZombiesPerRound(_roundState.currentRound)_roundState.zombiesSpawned=0 _roundState.zombiesKilled=0 _roundState.lastSpawnTime=_getTime()_roundState.spawnDelay=zombie.getSpawnDelay(_roundState.currentRound)_roundState.active=true for i=1,#_zombies do _zombies[i]=nil end return _roundState.currentRound end function zombie.isRoundComplete()return _roundState.zombiesKilled>=_roundState.zombiesTotal end function zombie.spawnZombie(zombieType)local spawns=_world.getZombieSpawns()if not spawns or#spawns==0 then return false end local openDoorIds={}local doors=_world.getDoors()for _,door in ipairs(doors)do if door.opened and door.id and door.id~=""then openDoorIds[door.id]=true end end local px,pz=_player.x,_player.z local available={}for _,sp in ipairs(spawns)do local eligible=false if not sp.requiredDoor or sp.requiredDoor==""then eligible=true elseif openDoorIds[sp.requiredDoor]then eligible=true else local dx=sp.x-px local dz=sp.z-pz if dx*dx+dz*dz<=25 then eligible=true end end if eligible then available[#available+1]=sp end end if#available==0 then for _,sp in ipairs(spawns)do if not sp.requiredDoor or sp.requiredDoor==""then available[#available+1]=sp end end end if#available==0 then available=spawns end local spawn=available[math.random(#available)]zombieType=zombieType or"normal"local hp=zombie.getZombieHealth(_roundState.currentRound)local speed=zombie.getZombieSpeed(_roundState.currentRound)if _ccz and _ccz.boss and _ccz.boss.getDef and _ccz.boss.getDef(zombieType)then local boss=_ccz.boss.spawn(zombieType,{x=spawn.x,y=spawn.y,z=spawn.z})if boss then boss.health=(zombieType=="panzer")and(hp*5)or hp boss.maxHealth=boss.health boss.lastAttackTime=0 boss.state="chasing"boss.velocityY=0 boss.onGround=true boss.height=1.8 _roundState.zombiesSpawned=_roundState.zombiesSpawned+1 return boss end return false end local z={x=spawn.x,y=spawn.y,z=spawn.z,type=zombieType,health=hp,maxHealth=hp,speed=speed,lastAttackTime=0,state="chasing",velocityY=0,onGround=true,height=1.8,currentFrame=1,animTimer=0,}_zombies[#_zombies+1]=z _roundState.zombiesSpawned=_roundState.zombiesSpawned+1 return z end function zombie.updateSpawning()if not _roundState.active then return end if _roundState.zombiesSpawned>=_roundState.zombiesTotal then return end local now=_getTime()if now-_roundState.lastSpawnTime>=_roundState.spawnDelay then zombie.spawnZombie()_roundState.lastSpawnTime=now end end local ATTACK_RANGE_XZ_SQ=2.2*2.2 local ATTACK_RANGE_Y=2.5 local ATTACK_DAMAGE=50 local ATTACK_COOLDOWN=1.5 local ZOMBIE_GRAVITY=-18 local function updateZombieAI(z,dt)if z.health<=0 then return end local ZNUDGE=0.1 local nudgeDirs={{ZNUDGE,0},{-ZNUDGE,0},{0,ZNUDGE},{0,-ZNUDGE}}for _=1,4 do if _world.checkCollision(z.x,z.y,z.z,0.4)then local moved=false for _,nd in ipairs(nudgeDirs)do if not _world.checkCollision(z.x+nd[1],z.y,z.z+nd[2],0.4)then z.x=z.x+nd[1]z.z=z.z+nd[2]moved=true break end end if not moved then break end else break end end local dx=_player.x-z.x local dy=_player.y-z.y local dz=_player.z-z.z local distSq=dx*dx+dz*dz if distSq<=ATTACK_RANGE_XZ_SQ and math.abs(dy)<=ATTACK_RANGE_Y then local now=_getTime()if now-z.lastAttackTime>=ATTACK_COOLDOWN then z.lastAttackTime=now if not _player.isDowned and not _player.inAfterlife then local IFRAMES=0.4 if not _player.lastHitTime or(now-_player.lastHitTime)>=IFRAMES then _player.health=_player.health-ATTACK_DAMAGE _player.stats.damageTaken=(_player.stats.damageTaken or 0)+ATTACK_DAMAGE _player.lastHitTime=now if _player.health<=0 then _player.isDowned=true _player.downedTime=now end end end end return end if math.abs(dy)>4 then else local moveX,moveZ local fdx,fdz=_nav.getFlowDir(z.x,z.z)if fdx and fdz then z._unreachableTime=nil local mag=math.sqrt(fdx*fdx+fdz*fdz)if mag>0 then moveX=(fdx/mag)*z.speed*dt moveZ=(fdz/mag)*z.speed*dt end else z._unreachableTime=(z._unreachableTime or 0)+dt if z._unreachableTime>=15.0 then z.health=0 return end local dist=math.sqrt(distSq)if dist>0 then moveX=(dx/dist)*z.speed*dt moveZ=(dz/dist)*z.speed*dt end end if moveX and moveZ then local newX=z.x+moveX local newZ=z.z+moveZ local blockedX=_world.checkCollision(newX,z.y,z.z,0.4)local blockedZ=_world.checkCollision(z.x,z.y,newZ,0.4)if not blockedX then z.x=newX end if not blockedZ then z.z=newZ end if(blockedX or blockedZ)and fdx and fdz then local sampleX=blockedX and z.x or newX local sampleZ=blockedZ and z.z or newZ local ndx,ndz=_nav.getFlowDir(sampleX,sampleZ)if ndx and ndz then local nm=math.sqrt(ndx*ndx+ndz*ndz)if nm>0 then local altX=(ndx/nm)*z.speed*dt local altZ=(ndz/nm)*z.speed*dt if blockedX and altX~=0 then if not _world.checkCollision(z.x,z.y,z.z+altZ,0.4)then z.z=z.z+altZ end elseif blockedZ and altZ~=0 then if not _world.checkCollision(z.x+altX,z.y,z.z,0.4)then z.x=z.x+altX end end end end end end end if z.onGround then z.velocityY=0 if not _world.isBlockSolid(z.x,z.y-0.05,z.z)then z.onGround=false end else z.velocityY=z.velocityY+ZOMBIE_GRAVITY*dt local newY=z.y+z.velocityY*dt if z.velocityY<0 and _world.isBlockSolid(z.x,newY-0.05,z.z)then z.y=math.floor(z.y-0.05)+1 z.velocityY=0 z.onGround=true else z.y=newY end end end function zombie.updateZombies(dt)_nav.update()local isModern=_settings and _settings.pointsSystem=="modern"for i=#_zombies,1,-1 do local z=_zombies[i]if z.health<=0 then if z._killedByPlayer then _roundState.zombiesKilled=_roundState.zombiesKilled+1 local pts if z._killedByMelee then pts=isModern and 130 or 130 elseif z._headshotKill then pts=isModern and 115 or 110 else pts=isModern and 90 or 60 end _player.points=_player.points+pts if _onKill then _onKill(z,_player)end elseif z._killedBySplash then _roundState.zombiesKilled=_roundState.zombiesKilled+1 if _onKill then _onKill(z,_player)end else _roundState.zombiesKilled=_roundState.zombiesKilled+1 end table.remove(_zombies,i)else updateZombieAI(z,dt)end end zombie.updateSpawning()end local _modelCache={}local ZOMBIE_COLORS={panzer=colors.red,normal=colors.green,}function zombie.renderAllZombies(renderedObjects)if not _frame then return end for _,z in ipairs(_zombies)do if z.health>0 then local color=ZOMBIE_COLORS[z.type]or colors.green local ckey=z.type or"normal"if not _modelCache[ckey]then if _world and _world.createBox then _modelCache[ckey]=_world.createBox(0.8,1.8,0.8,color)end end local model=_modelCache[ckey]if model then renderedObjects[#renderedObjects+1]=_frame:newObject(model,z.x,z.y+0.9,z.z)end end end end function zombie.clearModelCache()_modelCache={}end return zombie